import{c as a,Q as n,j as t,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"AOHP: An Open-Source OS-Level Agent Harness for Personalized, Efficient and Secure Interaction","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.23449","title":"AOHP: An Open-Source OS-Level Agent Harness for Personalized, Efficient and Secure Interaction","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.23449,"authors":["Shanhui Zhao","Jiacheng Liu","Guohong Liu","Jichao Yan","Jialei Ye","Yuhao Yang","Hao Wen","Shizuo Tian","Yizhen Yuan","Yuxuan Chen","Yunxin Liu","Ju Ren","Ya-Qin Zhang","Chao Huang","Yao Guo","Yuanchun Li"],"domains":["cs.AI","cs.OS"],"html":"https://arxiv.org/html/2606.23449v1","pdf_path":"pdfs/2606.23449.pdf","published_date":"2026-06-22T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-22-aohp-os-level-agent-harness-2606-23449.md","filePath":"research/papers/2026-06-22-aohp-os-level-agent-harness-2606-23449.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-06-22-aohp-os-level-agent-harness-2606-23449.md"};function i(s,e,l,c,h,d){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="aohp-an-open-source-os-level-agent-harness-for-personalized-efficient-and-secure-interaction" tabindex="-1">AOHP: An Open-Source OS-Level Agent Harness for Personalized, Efficient and Secure Interaction <a class="header-anchor" href="#aohp-an-open-source-os-level-agent-harness-for-personalized-efficient-and-secure-interaction" aria-label="Permalink to &quot;AOHP: An Open-Source OS-Level Agent Harness for Personalized, Efficient and Secure Interaction&quot;">​</a></h1><p><strong>Authors</strong>: Shanhui Zhao, Jiacheng Liu, Guohong Liu, Jichao Yan, Jialei Ye, Yuhao Yang, Hao Wen, Shizuo Tian, Yizhen Yuan, Yuxuan Chen, Yunxin Liu, Ju Ren, Ya-Qin Zhang, Chao Huang, Yao Guo, Yuanchun Li <strong>Published</strong>: June 22, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.23449" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.23449</a> · <a href="https://arxiv.org/html/2606.23449v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.23449 <strong>Categories</strong>: cs.AI, cs.OS <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.23449" target="_blank" rel="noreferrer">research/papers/pdfs/2606.23449.pdf</a> (17 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>AI agents are driving a new software paradigm, with the ability to autonomously call tools, extract information, manage memory, and complete tasks that span applications and data sources. Most existing end-user operating systems, however, are designed for application-centric workflows and offer little native support for AI agents. This mismatch limits the wider adoption of agents and leads to execution overhead and safety risks when running agents on conventional systems. While the concept of agent-native operating systems is emerging, the research community lacks an open testbed to explore the architectural primitives desired for agent-mediated interaction. We present AOHP (Android Open Harness Project), an OS-level agent harness built on the Android Open Source Project (AOSP). The core design principle of AOHP is to treat agents as first-class OS actors, enabling adaptive user interfaces and agent-friendly runtime environments. AOHP preserves the mature Android software and hardware ecosystem while introducing three agent-oriented system mechanisms: personalized service composition, efficient agent interfaces, and secure information flow. Based on preliminary experiments on challenging tasks covering key capabilities of OS agents, AOHP shows clear advantages in task completion (+21.12% completion rate), execution cost (-51.55% token cost), and security-policy compliance.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>AOHP（Android Open Harness Project）= 建在 AOSP 上的 <strong>OS 層 agent harness</strong>，核心原則「把 agent 當 first-class OS actor」（非 application-centric）。三大 agent-oriented 系統機制：</p><ol><li><strong>Personalized service composition</strong> — 依使用者組裝服務。</li><li><strong>Efficient agent interfaces</strong> — agent 友善的執行介面，降低觀測/操作開銷。</li><li><strong>Secure information flow</strong> — OS 層強制的安全資訊流，治理權限與洩漏風險。</li></ol><p>定位為開源 testbed，供社群探索 agent-native OS 的架構 primitive，同時保留成熟 Android 軟硬體生態。</p><h3 id="關鍵結果-preliminary" tabindex="-1">關鍵結果（preliminary） <a class="header-anchor" href="#關鍵結果-preliminary" aria-label="Permalink to &quot;關鍵結果（preliminary）&quot;">​</a></h3><ul><li>任務完成率 <strong>+21.12%</strong>。</li><li>token 成本 <strong>-51.55%</strong>。</li><li>安全策略合規性明顯優於常規系統執行。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>作者明示為 <strong>preliminary experiments</strong>；未列具體 limitation 章節，泛化性與長期穩定性待驗。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>「agent-friendly 執行環境」對應 harness 觀測/動作層</strong>：efficient agent interface 降 token 成本 -51.55%，與 NLAH / runtime-substrate 系列「介面適配優於模型調整」一脈；可作 best-practices/ 介面設計參考。</li><li><strong>secure information flow = OS 層 enforcement</strong>：與 Harness-MU（2606.21856）「治理交執行 hook 而非 LLM」同一思路的 OS 化版本，呼應 SafeHarness lifecycle security。</li><li>⚠️ 與本 workspace 場景錯位：AOHP 是 Android OS-level testbed，落地門檻高；列為域外參考而非可直接套用之 pattern（P2）。</li></ul>',18)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
